<?php
namespace App\Http\Controllers;use App\Models\{ProductionItem,PrintBatch};use App\Services\ProductionService;use Illuminate\Http\Request;
class ProductionController extends Controller{function __construct(private ProductionService $svc){}function dashboard(){$items=ProductionItem::with('decision')->get();$ready=$items->filter(fn($i)=>$this->svc->ready($i));return view('dashboard.index',['total'=>$items->count(),'ready'=>$ready->count(),'review'=>$items->where('match_status','REVIEW')->count(),'custom'=>$items->where('is_custom',true)->count(),'summary'=>$this->svc->summary($ready),'batches'=>PrintBatch::latest()->limit(5)->get()]);}function verification(){$items=ProductionItem::with('decision')->orderByRaw("CASE match_status WHEN 'REVIEW' THEN 0 WHEN 'MISSING' THEN 1 WHEN 'CUSTOM' THEN 2 ELSE 3 END")->orderBy('order_number')->get();foreach($items as $i){$i->ready_for_print=$this->svc->ready($i);$i->approval_current=$this->svc->current($i);}return view('production.verification',compact('items'));}function verify(Request $r,ProductionItem $item){$d=$r->validate(['decision'=>'required|in:CORRECT,WRONG'])['decision'];$this->svc->verify($item,$d,$r->user()->id);return back()->with('ok',$d==='CORRECT'?'Artwork approved.':'Artwork marked wrong.');}function queue(){$items=$this->svc->queue();return view('production.queue',['items'=>$items,'summary'=>$this->svc->summary($items),'materials'=>ProductionService::MATERIALS]);}function batch(Request $r){$b=$this->svc->batch($r->user()->id);return redirect('/batches/'.$b->id)->with('ok','Production batch created.');}function batches(){return view('batches.index',['batches'=>PrintBatch::latest()->get()]);}function showBatch(PrintBatch $batch){return view('batches.show',compact('batch'));}}
